/* Security hardening for data kept in the browser: whatever is read back from localStorage is trimmed and type-checked, so edited or corrupted storage cannot break or inject into the page. */
function clean(o){const t=(x,n)=>String(x==null?'':x).slice(0,n),a=x=>Array.isArray(x)?x:[];if(!o||typeof o!='object')return{};const p=o.profile;return{profile:p&&typeof p=='object'?{country:CUR[p.country]?p.country:'BD',board:t(p.board,80),cls:t(p.cls,40),lang:t(p.lang,20),subjects:a(p.subjects).map(x=>t(x,60)).slice(0,20),exam:t(p.exam,10),name:t(p.name,60),school:t(p.school,100),group:t(p.group,30),roll:t(p.roll,12),sec:t(p.sec,12),goal:t(p.goal,8)}:null,tasks:a(o.tasks).slice(0,500).map(x=>({title:t(x&&x.title,200),subject:t(x&&x.subject,60),date:t(x&&x.date,10),time:t(x&&x.time,5),dur:Math.min(240,Math.max(5,+(x&&x.dur)||45)),done:!!(x&&x.done),doneOn:x&&x.doneOn?t(x.doneOn,10):null})),attempts:a(o.attempts).slice(-200).map(x=>({date:+(x&&x.date)||0,subj:t(x&&x.subj,60),score:+(x&&x.score)||0,total:+(x&&x.total)||0,kind:t(x&&x.kind,8),used:+(x&&x.used)||0,subs:(()=>{const m={},src=x&&x.subs&&typeof x.subs=='object'?Object.entries(x.subs):[];src.slice(0,12).forEach(([k,z])=>{if(Array.isArray(z))m[t(k,60)]=[Math.max(0,+z[0]||0),Math.max(0,+z[1]||0)]});if(!src.length&&x&&Array.isArray(x.items)){try{Object.assign(m,subsOf(x.items.slice(0,60).map(z=>[z&&z[0],z&&z[1]?1:0])))}catch(e){}}return m})()})),cards:o.cards&&typeof o.cards=='object'?o.cards:{},notes:a(o.notes).slice(0,100).map(x=>({date:t(x&&x.date,30),sum:t(x&&x.sum,3000)})),bank:a(o.bank).slice(0,2000).map(x=>({t:t(x&&x.t,30),y:t(x&&x.y,10),b:t(x&&x.b,60),q:t(x&&x.q,500),a:t(x&&x.a,200),o:a(x&&x.o).slice(0,3).map(z=>t(z,200)),e:t(x&&x.e,300)}))}}
