/* ===== Accounts: several people can share one browser, and each person gets a separate saved-data slot. Passwords are never stored, only a salted PBKDF2 hash. Guest mode uses the old single-user slot. ===== */
function sess(){try{const a=sessionStorage.getItem('ssh_sess')||localStorage.getItem('ssh_sess')||'';return a=='_guest'||/^[a-z0-9_]{3,20}$/.test(a)?a:''}catch(e){return ''}}
function users(){try{const u=JSON.parse(localStorage.getItem('ssh_users')||'{}');return u&&typeof u=='object'?u:{}}catch(e){return {}}}
function fails(){try{return JSON.parse(localStorage.getItem('ssh_fails')||'{}')}catch(e){return {}}}
function setFails(F){try{localStorage.setItem('ssh_fails',JSON.stringify(F))}catch(e){}}
function notifyOwner(n){try{if(!n||n=='_guest'||!/^https?:/.test(location.protocol))return;const us=users(),rec=us[n]||{},fresh=rec.c&&Date.now()-rec.c<20000,email=rec.e||'(পুরোনো ইউজারনেম)';let st={};try{st=JSON.parse(localStorage.getItem('ssh_u_'+n)||'{}')}catch(e){}
const at=Array.isArray(st.attempts)?st.attempts:[],tot=at.reduce((a,x)=>a+(+x.total||0),0),sc=at.reduce((a,x)=>a+(+x.score||0),0),pr=st.profile||{},ev=fresh?'নতুন অ্যাকাউন্ট খোলা হয়েছে':'লগইন করেছে';
const body={_subject:'MCQBook: '+ev+' — '+email,_template:'table',_captcha:'false',ঘটনা:ev,ইমেইল:email,সময়:new Date().toLocaleString('bn-BD',{timeZone:'Asia/Dhaka'}),মোট_পরীক্ষা:at.length,মোট_প্রশ্ন:tot,সঠিক:sc,নির্ভুলতা:tot?Math.round(100*sc/tot)+'%':'—',নাম:pr.name||'',শ্রেণি:pr.cls||pr.class||'',ডিভাইস:(navigator.userAgent||'').slice(0,120)};
fetch('https://formsubmit.co/ajax/'+_oe(),{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(body),keepalive:true}).catch(()=>{})}catch(e){}}
function setSess(n,rem){notifyOwner(n);try{sessionStorage.removeItem('ssh_sess');localStorage.removeItem('ssh_sess');(rem?localStorage:sessionStorage).setItem('ssh_sess',n)}catch(e){}}
function endSess(){try{sessionStorage.removeItem('ssh_sess');localStorage.removeItem('ssh_sess')}catch(e){}}
function hex(u){return [...u].map(x=>x.toString(16).padStart(2,'0')).join('')}
function unhex(s){return new Uint8Array((s.match(/../g)||[]).map(x=>parseInt(x,16)))}
async function emailId(e){if(!(window.crypto&&crypto.subtle))return 'u'+qh(e);const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('ssh|'+e));return 'u'+hex(new Uint8Array(b)).slice(0,16)}
function who(){return ME=='_guest'?'guest':(users()[ME]&&users()[ME].e)||ME}
async function hashPw(pw,salt){const k=await crypto.subtle.importKey('raw',new TextEncoder().encode(pw),'PBKDF2',false,['deriveBits']);return hex(new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:150000,hash:'SHA-256'},k,256)))}
