function qh(s){let h=5381;for(let i=0;i<s.length;i++)h=((h*33)^s.charCodeAt(i))>>>0;return h.toString(36)}
let LR='',KEEP=0;
function anim0(){document.querySelectorAll('[data-p]').forEach(e=>{const p=+e.dataset.p,sp=e.firstChild;let t0=null;const f=ts=>{if(!t0)t0=ts;const k=Math.min(1,(ts-t0)/900),v=Math.round(p*(1-Math.pow(1-k,3)));e.style.background='conic-gradient(var(--pr) '+v+'%,var(--bd) 0)';sp.textContent=v+'%';if(k<1)requestAnimationFrame(f)};requestAnimationFrame(f)})}

