function confetti(){if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;const cols=['#b8912f','#e2c26b','#7a1f35','#14213d','#157347','#fffdf9'];for(let i=0;i<70;i++){const d=document.createElement('i');d.className='cf';d.style.left=(Math.random()*100)+'vw';d.style.background=cols[i%cols.length];d.style.setProperty('--dx',(Math.random()*160-80)+'px');d.style.setProperty('--r',(Math.random()*900-450)+'deg');d.style.animationDuration=(2.2+Math.random()*2)+'s';d.style.animationDelay=(Math.random()*.6)+'s';document.body.appendChild(d);setTimeout(()=>d.remove(),5200)}}
