function rpt(){const R={n:S.attempts.length,q:0,ok:0,sec:0,bySub:{},kinds:{board:0,mock:0,quiz:0}};S.attempts.forEach(a=>{R.q+=a.total;R.ok+=a.score;R.sec+=a.used||0;if(R.kinds[a.kind]!==undefined)R.kinds[a.kind]++;Object.entries(a.subs||{}).forEach(([s,z])=>{const r=R.bySub[s]=R.bySub[s]||[0,0];r[0]+=z[0];r[1]+=z[1]})});return R}
const rcol=p=>p>=70?'var(--ok)':p>=40?'var(--gold)':'var(--bad)';
const MOTI=[[0,'শুরুটা করে ফেলো','একটি ছোট কুইজ দিয়েই শুরু করো। প্রতিদিনের অল্প অনুশীলনই বড় ফল আনে।','🌱'],[30,'হাল ছেড়ো না','এখনই সবচেয়ে ভালো সময় শুরু করার। প্রতিটি ভুল তোমাকে শেখায়, ছোট ছোট সেট ধরে এগোও।','💪'],[50,'ঠিক পথেই আছো','ভিত তৈরি হচ্ছে। পাঠ্যবই একবার ঝালিয়ে আবার চেষ্টা করো, উন্নতি চোখে পড়বে।','🚀'],[70,'ভালো এগোচ্ছো','অনেকটা পথ পেরিয়েছো। দুর্বল বিষয়ে আরেকটু সময় দিলেই ৮০%+ ছুঁতে পারবে।','🔥'],[85,'অসাধারণ!','জিপিএ ৫ এখন হাতের নাগালে। এই ধারা ধরে রাখো আর মাঝে মাঝে পুরোনো অধ্যায় ঝালিয়ে নাও।','🏆']];
function moti(p,n){if(!n)return MOTI[0];let m=MOTI[1];MOTI.forEach(x=>{if(x[0]&&p>=x[0])m=x});return m}
function motiCard(R,acc){const m=moti(acc,R.q);let weak='';const w=Object.entries(R.bySub).filter(x=>x[0]!='Sample'&&x[1][1]>=5).map(([k,v])=>[k,Math.round(100*v[0]/v[1])]).sort((a,b)=>a[1]-b[1])[0];if(w&&w[1]<80)weak=`<p class='mu' style='margin:.5rem 0 0'>এখন বেশি মনোযোগ দাও: <b>${ed(w[0])}</b> (${w[1]}%)</p>`;return `<div class='card moti' style='--mc:${rcol(acc)}'><div class='moti-e' aria-hidden='true'>${emo(m[3])}</div><div class='moti-b'><small class='mu'>তোমার জন্য বার্তা</small><h3>${m[1]}</h3><p>${m[2]}</p><div class='bar'><i style='width:${R.q?acc:0}%'></i></div>${weak}</div></div>`}
