function donut(ok,total){const p=total?Math.round(100*ok/total):0;return `<svg class="rgs" width="170" height="170" viewBox="0 0 36 36" role="img" aria-label="নির্ভুলতা ${p}%"><circle cx="18" cy="18" r="15.9155" fill="none" stroke="var(--bad)" stroke-opacity=".28" stroke-width="3.6"/><circle class="rg" cx="18" cy="18" r="15.9155" fill="none" stroke="var(--ok)" stroke-width="3.6" stroke-linecap="${p>0&&p<100?'round':'butt'}" pathLength="100" stroke-dasharray="${p} ${100-p}" transform="rotate(-90 18 18)"/><text x="18" y="18.8" text-anchor="middle" font-size="8.6" font-weight="700" fill="currentColor">${p}%</text><text x="18" y="24" text-anchor="middle" font-size="3.2" fill="var(--mu)">নির্ভুলতা</text></svg>`}
function cols(A){const n=A.length,W=300,H=130,bw=Math.min(28,Math.floor(W/n)-8);return `<svg viewBox="0 0 ${W} ${H+24}" class="cols" role="img" aria-label="সাম্প্রতিক স্কোরের চার্ট">`+[0,50,100].map(g=>{const y=H+6-g*H/100*.92;return `<line x1="0" x2="${W}" y1="${y}" y2="${y}" stroke="var(--bd)" stroke-dasharray="3 3"/>`}).join('')+A.map((a,i)=>{const p=a.total?Math.round(100*a.score/a.total):0,h=Math.max(2,p*H/100*.92),x=(i+.5)*W/n-bw/2,y=H+6-h;return `<g><title>${p}% (${a.score}/${a.total})</title><rect class="cb" x="${x}" y="${y}" width="${bw}" height="${h}" rx="3" fill="${rcol(p)}"/><text x="${x+bw/2}" y="${y-3}" text-anchor="middle" font-size="9" fill="currentColor">${p}</text><text x="${x+bw/2}" y="${H+20}" text-anchor="middle" font-size="9" fill="var(--mu)">${i+1}</text></g>`}).join('')+`</svg>`}
