function qkPool(s){return shuffle(BQ.filter(q=>q.s==s))}
function qk0(s){return{ph:'run',sub:s,pool:qkPool(s),k:0,pick:undefined,log:[],streak:0,best:0,t0:Date.now(),saved:false,round:1}}
function qkSave(){if(!QK.log||!QK.log.length||QK.saved)return;QK.saved=true;QK.used=Math.round((Date.now()-QK.t0)/1000);S.attempts.push({date:Date.now(),subj:'Quick practice',kind:'quiz',used:QK.used,score:QK.log.filter(x=>x.c).length,total:QK.log.length,subs:subsOf(QK.log.map(x=>[x.h||'x',x.c]))});save()}
function quickView(){if(QK.ph=='setup'||!QK.sub)return learnView();
if(QK.ph=='done'){const L=QK.log;return `${subHero(QK.sub,'কুইক প্র্যাকটিস')}<h2>তোমার ফল</h2>${sumHtml(L.map(x=>({c:x.c?0:1,b:x.b})),QK.used||0,0)}<div class="card norv"><div class="row"><button class="p" data-a="qkreset">আবার শুরু করো</button><button data-a="qkback">অন্য বিষয়</button><a class="btn" href="#/report">${ic('report')} পুরো রিপোর্ট</a></div></div>`}
const q=QK.pool[QK.k],a=QK.pick!==undefined,n=QK.log.length,ok=QK.log.filter(x=>x.c).length,acc=n?Math.round(100*ok/n):0,key=QK.k+':'+QK.round,fresh=QK.shown!==key,dir=QK.dir||'',good=a&&QK.pick===q.a;QK.shown=key;QK.dir='';
return `<div class="row" style="justify-content:space-between"><button class="back" data-a="qkback">← বিষয় বদলাও</button><span class="tag">${ed(QK.sub)}</span></div><div class="qks"><div class="st"><b>${n}</b><small>উত্তর দেওয়া</small></div><div class="st"><b class="okc">${ok}</b><small>সঠিক</small></div><div class="st"><b>${acc}%</b><small>নির্ভুলতা</small></div><div class="st fire ${QK.streak>=3?'hot':''}"><b>${ic('flame')} ${QK.streak}</b><small>টানা সঠিক</small></div></div>
<div class="card norv mq ${fresh?(dir=='r'?'qin-r':'qin-f'):''}"><small class="mu">প্রশ্ন <b>${a?n:n+1}</b> · যতখুশি চালিয়ে যাও</small><p class="mqt" style="white-space:pre-line"><b>${esc(q.q)}</b></p><div class="mopts">${q.o.map((o,j)=>OPT(o,j,(fresh?'':'noin ')+(a?(j==q.a?'ok':QK.pick==j?'err':'dim'):'')+(QK.pick===j?' just':''),`data-a="qkpick" data-j="${j}" style="--d:${j*.06}s" ${a?'disabled':''}`)).join('')}</div>${a?`<div class="fb ${good?'good':'bad'}"><b>${good?'সঠিক উত্তর!'+(QK.streak>=3?' টানা '+QK.streak+'টি।':''):'ভুল হয়েছে। সঠিক উত্তর: '+'ABCD'[q.a]+'. '+esc(q.o[q.a])}</b>${q.e?`<span class="mu" style="display:block;margin-top:.3rem">${esc(q.e)}</span>`:''}${isP(q)?'':`<span class="src">${ic('pin')} ${ed(q.b)} · ${esc(q.y)}</span>`}</div>`:''}<div class="qx"><button class="p grow ${a?'pulse':''}" data-a="qknext" ${a?'':'disabled'}>পরের প্রশ্ন →</button><button data-a="qkend">শেষ করো</button></div><small class="mu kbh">কিবোর্ড: 1–4 = উত্তর, Enter বা → = পরের প্রশ্ন</small></div>`}
